@layer kg.components {
  .kg-orb__halo {
    background: radial-gradient(
      closest-side,
      color-mix(in oklab, var(--_c) 45%, transparent),
      color-mix(in oklab, var(--_c) 12%, transparent) 55%,
      transparent
    );
    animation: kg-orb-breathe calc(9s / var(--_speed)) var(--kg-ease-in-out) infinite
      alternate;
  }

  .kg-orb__sphere {
    background: radial-gradient(
      circle at 34% 28%,
      color-mix(in oklab, var(--_warm), white 45%) 0%,
      var(--_warm) 16%,
      var(--_c) 38%,
      var(--_deep) 78%,
      color-mix(in oklab, var(--_deep) 60%, var(--kg-bg)) 100%
    );
    box-shadow:
      inset -1.5rem -2rem 3rem color-mix(in oklab, var(--kg-bg) 45%, transparent),
      0 2rem 4rem -1.5rem color-mix(in oklab, var(--_c) 40%, transparent);
  }

  .kg-orb__swirl {
    background: conic-gradient(
      from 0deg,
      transparent 0deg,
      color-mix(in oklab, var(--_warm) 55%, transparent) 70deg,
      transparent 150deg,
      color-mix(in oklab, var(--_c) 50%, transparent) 230deg,
      transparent 300deg
    );
    animation: kg-orb-spin calc(16s / var(--_speed)) linear infinite;
  }

  .kg-orb__shine {
    background: radial-gradient(closest-side, color-mix(in oklab, white 55%, transparent), transparent);
  }

  /* The orbit light: a conic sweep masked down to a hairline ring just outside the sphere. */
  .kg-orb__rim {
    background: conic-gradient(
      from 0deg,
      transparent 0deg 220deg,
      color-mix(in oklab, var(--_warm) 90%, transparent) 300deg,
      transparent 360deg
    );
    mask-image: radial-gradient(closest-side, transparent 96%, #000 97.5%, transparent 100%);
    animation: kg-orb-spin calc(7s / var(--_speed)) linear infinite reverse;
  }

  .kg-orb__layer * {
    animation-play-state: var(--kg-orb-state, running);
  }

  @media (prefers-reduced-motion: reduce) {
    .kg-orb__layer * {
      animation: none;
    }
  }

  [data-kg-motion="reduce"] .kg-orb__layer * {
    animation: none;
  }

  @keyframes kg-orb-spin {
    to {
      transform: rotate(1turn);
    }
  }

  @keyframes kg-orb-breathe {
    from {
      transform: scale(0.92);
    }
    to {
      transform: scale(1.06);
    }
  }
}

import {
  type CSSProperties,
  forwardRef,
  type HTMLAttributes,
  type ReactNode,
} from "react"
import { variants } from "../lib/utils/variants"
import { backdropRoot, hasChildren } from "../aurora/internal/backdrop"

export interface OrbProps extends HTMLAttributes<HTMLDivElement> {
  /** Any CSS color. Defaults to ink, warmed with peach paper. */
  color?: string
  /** Diameter as any CSS length. */
  size?: string
  /** Where the sphere sits inside the section. */
  position?: "center" | "top" | "bottom"
  /** Rotation speed multiplier; 0 holds it still. */
  speed?: number
  /** Strength of the surrounding glow, 0–1. */
  glow?: number
  children?: ReactNode
}

const orbLayer = variants({
  base: "kg-orb__layer pointer-events-none absolute inset-0 z-0 grid overflow-hidden",
  variants: {
    position: {
      center: "place-items-center",
      top: "[place-items:start_center] pt-[6%]",
      bottom: "[place-items:end_center] pb-[6%]",
    },
  },
  defaults: { position: "center" },
})

/**
 * A lit sphere with a slow inner swirl and an orbit light sweeping its rim. Layers of radial and
 * conic gradients turned on transform-only loops. Pure CSS, server safe.
 */
export const Orb = forwardRef<HTMLDivElement, OrbProps>(
  (
    {
      color,
      size = "min(56%, 22rem)",
      position = "center",
      speed = 1,
      glow = 0.6,
      className,
      style,
      children,
      ...props
    },
    ref,
  ) => {
    const wrapper = hasChildren(children)
    return (
      <div
        ref={ref}
        {...backdropRoot(
          "kg-orb absolute inset-0 overflow-hidden pointer-events-none data-wrapper:relative data-wrapper:inset-auto data-wrapper:isolate data-wrapper:pointer-events-auto [--_c:var(--kg-orb-color,var(--kg-ink))] [--_warm:color-mix(in_oklab,var(--_c),var(--kg-paper-peach)_50%)] [--_deep:color-mix(in_oklab,var(--_c)_40%,var(--kg-bg))] [--_speed:var(--kg-orb-speed,1)]",
          className,
          wrapper,
        )}
        data-position={position}
        style={
          {
            ...(color ? { "--kg-orb-color": color } : null),
            "--kg-orb-size": size,
            "--kg-orb-speed": Math.max(speed, 0.001),
            "--kg-orb-state": speed === 0 ? "paused" : "running",
            "--kg-orb-glow": Math.min(Math.max(glow, 0), 1),
            ...style,
          } as CSSProperties
        }
        {...props}
      >
        <div className={orbLayer({ position })} aria-hidden="true">
          <div className="kg-orb__body relative aspect-square w-[var(--kg-orb-size,22rem)]">
            <div className="kg-orb__halo absolute -inset-[45%] rounded-full opacity-[var(--kg-orb-glow,0.6)]" />
            <div className="kg-orb__sphere absolute inset-0 overflow-hidden rounded-full">
              <div className="kg-orb__swirl absolute -inset-[20%] rounded-full blur-[1.2rem] mix-blend-soft-light" />
              <div className="kg-orb__shine absolute top-[10%] left-[18%] h-[22%] w-[34%] rotate-[-28deg] rounded-full" />
            </div>
            <div className="kg-orb__rim absolute -inset-[3%] rounded-full" />
          </div>
        </div>
        {wrapper && <div className="kg-orb__content relative z-1">{children}</div>}
      </div>
    )
  },
)

Orb.displayName = "Orb"
